<template><dialog ref="dialog" @cancel.prevent="close" @click.self="close" class="m-auto w-[calc(100%-2rem)] max-w-md rounded-2xl border border-white/15 bg-[#111] p-5 text-white backdrop:bg-black/70"><form @submit.prevent="save"><header class="mb-5 flex items-center justify-between gap-3"><h2 class="text-lg font-medium">Configuración de mi cuenta</h2><DashboardHelp label="Nombre de usuario" text="Puedes cambiar el nombre que se muestra en tu cuenta y en tus citas. El correo, la contraseña y el rol se mantienen." /></header><label class="block text-sm text-white/60">Nombre<input v-model="name" required maxlength="120" :disabled="busy" class="mt-2 min-h-11 w-full rounded-lg border border-white/20 bg-neutral-950 px-3 text-white focus:outline-[#ffb700]" /></label><p v-if="error" role="alert" class="mt-3 text-sm text-red-300">{{ error }}</p><footer class="mt-6 flex justify-end gap-2"><button type="button" :disabled="busy" @click="close" class="min-h-11 rounded-lg border border-white/20 px-4 text-sm">Cerrar</button><button :disabled="busy || !name.trim() || name.trim() === user.user?.name" class="min-h-11 rounded-lg bg-[#ffb700] px-4 text-sm font-medium text-black disabled:opacity-40">{{ busy ? 'Guardando…' : 'Guardar nombre' }}</button></footer></form></dialog></template>
<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from "vue";import api from "@/lib/axios";import {useUserStore} from "@/stores/user";import {toast} from "@/lib/notifications";import DashboardHelp from "@/components/admin/DashboardHelp.vue";
const emit=defineEmits<{close:[]}>(),user=useUserStore(),name=ref(user.user?.name||""),busy=ref(false),error=ref(""),dialog=ref<HTMLDialogElement>();
function close(){if(!busy.value)emit('close');}
async function save(){if(busy.value||!name.value.trim())return;busy.value=true;error.value="";try{const {data}=await api.patch('/users/me/profile',{name:name.value.trim()});if(user.user)user.user.name=data.name;toast.success(data.msg);busy.value=false;close();}catch(e:any){error.value=e?.response?.data?.msg||'No pudimos guardar tu nombre.';}finally{busy.value=false;}}
onMounted(()=>dialog.value?.showModal());onBeforeUnmount(()=>dialog.value?.close());
</script>